INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'adjust.hint', 'es', 'Mueva un país a otra ola, o fije su propia fecha de inicio. El gráfico y los tiempos transcurridos se redibujan a partir de sus cambios; nada más en la página se mueve.');
