INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'adjust.nodeadline', 'es', 'sin fecha límite');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'adjust.note', 'es', 'Los cambios solo existen en esta página &mdash; no se guarda nada, y al recargar se restablece el calendario planificado hacia atrás. Un país que mueva más allá de su propia fecha límite sigue visible y se señala arriba, porque un plan que incumple una fecha es una decisión y no un error.');
