INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'assumptions.durations', 'es', 'Las duraciones son por país. Los países que comparten fecha de puesta en marcha forman una ola, así que una ola de cinco países cuesta aproximadamente cinco frentes-país de esfuerzo, repartidos entre tantos frentes como pueda llevar realmente a la vez.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'assumptions.grades', 'es', 'Cada cifra muestra de dónde salió. <span class="tag tA">A</span> medida y primaria &middot; <span class="tag tB">B</span> organismo creíble, sin fuente &middot; <span class="tag tD">D</span> nuestra estimación. Un valor suyo siempre gana a nuestro valor por defecto &mdash; para eso está este panel.');
