INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'assumptions.placeholders', 'es', 'Estas cifras son <strong>solo valores provisionales</strong>. Sustitúyalas por estimaciones presupuestarias de su proveedor y trate el ROI como ilustrativo hasta disponer de datos reales.');
