INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'basis.ap.just2', 'es', ' Al cumplimiento solo se le atribuyen la captura y la validación &mdash; 9 de los 21 minutos de tramitación de AP {0} &mdash; porque la revisión y la aprobación son decisiones de negocio que ningún formato de factura elimina.');
