INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'basis.arShare2.just', 'es', 'Costo de emisión a partir de las cifras de canal de la ATO {0} sobre su propio reparto 60/40 {1}. Rango de reducción {2}. La proporción de emisión estructurada es suya, y nuestro valor por defecto es deliberadamente la medición más alta de que disponemos {3}.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'basis.cycle2.just', 'es', 'Las consultas de proveedores ocupan el <strong>12,8 %</strong> del tiempo del personal de AP frente al <strong>24,0 %</strong> {0}; tiempo de ciclo <strong>2,9 días</strong> frente a <strong>13,5</strong> {1}; <strong>15 % menos consultas</strong> en un trust {2}. Asociaciones con un AP de alto rendimiento, no efectos medidos.');
