INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'basis.paper.just', 'es', 'Papel 30,87 AUD frente a 9,18 AUD por una e-factura {0}; su propio gasto en impresión, franqueo y archivo es el mejor dato de entrada.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'basis.penalty.just', 'es', '{0} de sus países publican un régimen sancionador cuantificado {1}. Dimensiónelo país por país; no existe un agregado creíble.');
