INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'basis.tax.just', 'es', 'Mecanismo respaldado {0}; facturas por ETC {1}; la proporción dentro del alcance es nuestra y lleva tope {2}. Ahorrado en cualquiera de los dos alcances &mdash; el esfuerzo de reporte baja con la construcción de cumplimiento, no con un cambio de flujo de trabajo.');
