INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.durationsShort', 'es', 'estimaciones de profesionales');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.excRate2', 'es', 'tasa de excepción de mercado del 18,4 %');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.excSplit', 'es', '11,1 % frente a 20,9 %');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeA', 'es', 'Nota A');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeA.body', 'es', 'Ardent Partners 2025 (costo, tiempo de ciclo, tasas de excepción y de consulta de proveedores) &middot; ATO / Deloitte Access Economics (papel frente a PDF frente a e-factura, datos de 2016, indicado) &middot; OCDE DCTR 2026 (mecanismo) &middot; los datos de seguimiento propios de este sitio.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeA.tag', 'es', 'medida &amp; primaria');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeB', 'es', 'Nota B');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeB.body', 'es', 'HMRC/DBT: reducción de costos del 60&ndash;80 % y tasa de error manual de en torno al 10 %. Ambas aparecen en una consulta del Gobierno británico, ninguna con una fuente dentro. Se usan aquí, dejando constancia de esa laguna.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeB.tag', 'es', 'organismo creíble, sin fuente');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeC', 'es', 'Nota C');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeC.body', 'es', 'Las cifras del NHS trust (24 h frente a 10 días, pago al doble de velocidad, 15 % menos consultas) proceden de una única organización sin nombre y sin fecha. Las cifras de la brecha del IVA son de la Comisión Europea y CASE, no de la OCDE, y los propios análisis por país de la Comisión atribuyen el cambio a la recuperación económica y no al reporte digital.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeC.tag', 'es', 'anécdota, no una referencia');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeD', 'es', 'Nota D');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeD.body', 'es', 'El tiempo de resolución por factura con errores, los costos cargados por ETC, el peso del esfuerzo fiscal. Son nuestras estimaciones de partida, mostradas para que pueda sustituirlas por las suyas.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeD.tag', 'es', 'supuesto suyo');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeLabel', 'es', 'Nivel de evidencia {0}');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.hmrcAto', 'es', 'HMRC, corroborado por la ATO');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.hmrcRate', 'es', 'Consulta de HMRC');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.nhsQuery', 'es', '15 % menos consultas');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.oecdDctr', 'es', 'OCDE DCTR, 2026');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.ourAssumption', 'es', 'nuestro supuesto');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.site.body', 'es', 'Los datos de mandatos proceden del seguimiento propio de este sitio: estado, modelo y fechas límite por país, cada uno trazable hasta el instrumento jurídico citado en la ficha detallada de ese país &mdash; esa es la garantía, y no una afirmación sobre lo reciente de la comprobación.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.siteLabel', 'es', 'Fuente: datos de seguimiento');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.sourceLink', 'es', 'fuente');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.taskSplit', 'es', 'el reparto de tareas');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.trackerDates', 'es', 'fechas del seguimiento');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.treasury', 'es', 'Use su propia tasa de tesorería para todo lo que vaya a firmar');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.whyNot', 'es', 'por qué no');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.whyNotAll', 'es', 'por qué no todas');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.yourCall', 'es', 'usted decide');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.yourMins', 'es', 'su tiempo de resolución');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.yourShare', 'es', 'su cifra');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.yours.body', 'es', 'Supuesto suyo. No se afirma nada sobre esta cifra &mdash; se muestra para que se pueda discutir el modelo en lugar de creerlo.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'footer.pdf', 'es', 'Esta herramienta modela un caso de negocio; no es asesoramiento fiscal, jurídico ni de inversión. Las cifras marcadas con D son nuestras estimaciones de partida y no referencias &mdash; sustitúyalas por las suyas antes de que una decisión dependa de ellas.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'footer.text', 'es', '<strong>The E-Invoicing Compliance Corner</strong> &mdash; planificador de ROI &amp; olas. Cada fecha de mandato aquí es trazable hasta el instrumento jurídico citado en la ficha detallada de ese país, que es donde debe comprobarse. Las cifras de referencia llevan el nivel de evidencia indicado junto a cada una. Esta herramienta modela un caso de negocio; no es asesoramiento fiscal, jurídico ni de inversión.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'fx.converted', 'es', 'Convertido a un <strong>tipo fijo</strong> de 1 {0} = {1} USD &mdash; no se actualiza a diario.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'fx.convertedDated', 'es', 'Convertido a un <strong>tipo fijo</strong> de 1 {0} = {1} USD, contado {2} &mdash; no se actualiza a diario.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'gate.body2', 'es', 'Sus cifras están arriba y son suyas. Una cuenta gratuita guarda los países que ha seleccionado, le avisa por correo cuando uno de estos mandatos cambia de verdad, y recuerda sus supuestos para la próxima vez. Solo hace falta un código de 6 dígitos, sin contraseña &mdash; y usted no sale de esta página.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'gate.cta2', 'es', 'Crear una cuenta gratuita');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'gate.eyebrow', 'es', 'Cuenta gratuita');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'gate.signin', 'es', '¿Ya tiene una? {0}.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'gate.signin.link', 'es', 'Iniciar sesión');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'gate.title', 'es', 'Guarde esto y entérese cuando cambie');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'grp.named', 'es', 'Nombrado, no cuantificado &mdash; real, pero este modelo no inventará una cifra para ello');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'grp.priced', 'es', 'Cuantificado &mdash; contabilizado en el caso de negocio');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.capture', 'es', '<strong>La plantilla de captura vale más que todo el ahorro de procesamiento.</strong> {0} de costo de captura liberado frente a {1} de reducción total del procesamiento de AP. Son dos caminos hacia el mismo dinero, así que el primero no puede superar al segundo &mdash; revise la tarifa de captura de datos y el costo de AP por factura, porque una de las dos está mal.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.excGap', 'es', '<strong>Este modelo elimina más excepciones de las que separan al mejor cuartil de AP de todos los demás.</strong> Su tasa de error y su supuesto de eliminación sacan juntos {0} puntos de facturas del circuito de excepciones; Ardent mide toda la brecha entre Best-in-Class y el resto en {1} puntos {2}, sumando todas las causas y con la facturación electrónica como un factor entre varios. Baje la tasa de error o el porcentaje de eliminación &mdash; tal como está, la fila de retrabajo reclama más de lo que logran los mejores del mercado.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.heading', 'es', '{0} {1} que revisar antes de usar estas cifras');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.late.one', 'es', '<strong>{0} fecha de inicio fijada termina después de la fecha límite.</strong> {1}. Puede ser deliberado &mdash; un retraso asumido es una decisión que un consejo puede tomar &mdash; pero el plan de abajo ya no cumple esa fecha.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.late.other', 'es', '<strong>{0} fechas de inicio fijadas terminan después de la fecha límite.</strong> {1}. Puede ser deliberado &mdash; un retraso asumido es una decisión que un consejo puede tomar &mdash; pero el plan de abajo ya no cumple esas fechas.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.mistimed.disc', 'es', '{0} &mdash; {1} (planificado como discrecional)');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.mistimed.one', 'es', '<strong>{0} país seleccionado tiene una obligación anterior a la fecha para la que planifica este plan.</strong> {1}. Son obligaciones vigentes y con fecha que el seguimiento público de este sitio no muestra, así que el plan de olas no las programa. El margen que se muestra para él es mayor que el que realmente tiene.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.mistimed.other', 'es', '<strong>{0} países seleccionados tienen obligaciones anteriores a la fecha para la que planifica este plan.</strong> {1}. Son obligaciones vigentes y con fecha que el seguimiento público de este sitio no muestra, así que el plan de olas no las programa. El margen que se muestra para ellos es mayor que el que realmente tienen.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.mistimed.planned', 'es', '{0} &mdash; {1} (previsto para {2})');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.payback', 'es', '<strong>Recuperación en menos de un mes.</strong> Ningún programa de facturación electrónica se amortiza tan rápido. Revise los volúmenes y los costos por factura &mdash; uno de los dos está desviado en un orden de magnitud, y el resto de esta página lo hereda.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.selectFirst', 'es', '<strong>Seleccione primero al menos un país.</strong> El plan de olas, el número de integraciones y todo el lado de la inversión se construyen a partir de los países en los que factura &mdash; sin ninguno elegido no hay programa que cuantificar.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.soon', 'es', '<strong>{0} debe empezar en 90 días</strong> para cumplir la fecha límite publicada con sus supuestos de fase actuales.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.taxCap', 'es', '<strong>El ahorro en esfuerzo fiscal lleva tope, y el tope está actuando.</strong> {0} implicaría el {1} % de su esfuerzo de AP; el modelo no reconoce más del {2} %, porque la magnitud es un supuesto nuestro y no una referencia, y sin tope se dispararía. Añadir más países no moverá la cifra indirecta &mdash; aunque seguirá sumando costo, y esa es la asimetría honesta.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.zeroInt.one', 'es', '<strong>{0} país seleccionado tiene mandato, pero el modelo ha cuantificado cero integraciones.</strong> Eso no es un programa barato, es un cálculo roto &mdash; trate cada cifra de abajo como poco fiable hasta que se explique.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.zeroInt.other', 'es', '<strong>{0} países seleccionados tienen mandato, pero el modelo ha cuantificado cero integraciones.</strong> Eso no es un programa barato, es un cálculo roto &mdash; trate cada cifra de abajo como poco fiable hasta que se explique.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.arShare', 'es', 'La proporción de las facturas que usted EMITE que ya salen como e-facturas estructuradas — no PDF por correo, que el receptor aún tiene que leer y capturar. Un ahorro solo se puede tomar una vez: lo que ya sale estructurado ya lo ha tomado. Valor por defecto 64 %: Billentis sitúa ahí a Europa y en 29 % al mundo.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.cImplC', 'es', 'Costo único de conectar un sistema de facturación a un país COMPLEJO — clearance o reporte, así que certificación, gestión de errores y conciliación de estados. Un valor provisional, como arriba. Sustitúyalo por su oferta.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.cImplS', 'es', 'Costo único de conectar un sistema de facturación a un país SIMPLE — un intercambio de 4 esquinas, sin la administración tributaria de por medio. Un valor provisional: ninguna firma de analistas publica una cifra creíble por país. Sustitúyalo por su oferta.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.cPlat', 'es', 'Cuotas anuales de plataforma, red o punto de acceso en todos los países del alcance. Obtenidas de una tarifa por documento aplicada a sus volúmenes de AP y AR juntos. Un valor provisional — los precios de los proveedores varían en un orden de magnitud. Un valor que usted escriba deja de seguir a los volúmenes.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.cRun', 'es', 'Sus propios costos anuales de operar el servicio una vez en marcha: supervisión, gestión de excepciones y seguimiento de los cambios de mandato. Un valor provisional, y habitualmente subestimado — el trabajo sobre los mandatos no termina nunca.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.colBanks', 'es', 'Si un ahorro llega con la propia construcción de cumplimiento, o si necesita un programa de cambio de AP más amplio que quizá no esté llevando. Las facturas estructuradas se contabilizan y se liquidan sin él; un rediseño de flujo de trabajo no. Cada fila dice cuál de los dos, y por qué, en su justificación.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.complexity', 'es', 'COMPLEJO cuando la administración tributaria ve datos a nivel de factura: clearance, un modelo de 5 esquinas o reporte digital. SIMPLE en los demás casos. Asignado a mano país por país en el seguimiento, no deducido de un texto. Determina tanto la tarifa de integración como las duraciones de fase.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.costAR', 'es', 'Costo de emitir hoy una factura a cliente. Menor que la cifra de AP porque la emisión no tiene cotejo ni aprobación. Obtenido de los costos de canal de ATO / Deloitte usando el propio reparto 60/40 de la ATO (nota B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.costNow', 'es', 'Costo totalmente cargado de tramitar hoy una factura de proveedor — personas, sistemas, excepciones, aprobaciones, no solo licencias. Forma la base a la que se aplica la reducción. Media de mercado de Ardent Partners, datos de 2025 (nota A).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.countries', 'es', 'Datos de mandatos actualizados del seguimiento propio de este sitio — estado, modelo y fecha límite por país, cada uno trazable hasta el instrumento jurídico citado en la ficha detallada de ese país. El dato de entrada que más cambia el resultado.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.cur', 'es', 'Convierte todos los importes de la página, incluidos los valores de referencia por defecto y cualquier valor que haya sustituido. El tipo es un cambio de contado tomado en la fecha indicada y almacenado, no actualizado a diario, para que el mismo escenario dé la misma respuesta meses después. Use su propia tasa de tesorería para todo lo que vaya a firmar.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.eShare', 'es', 'La proporción de sus facturas de proveedor que ya llegan como e-facturas estructuradas — no PDF, que aún hay que leer y capturar. Un ahorro solo se puede tomar una vez, así que esta es la mayor palanca sobre la fila de AP. Ardent sitúa el mercado en el 51 % (nota B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.erp', 'es', 'Sistemas ERP o de facturación distintos que deben emitir o recibir facturas — no entidades jurídicas; las entidades que comparten sistema cuentan una vez. Cada sistema después del primero añade un 12 % al diseño y la construcción, con tope en +60 %.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.errElim', 'es', 'Qué proporción de las facturas con errores de hoy elimina realmente la facturación electrónica. Valor por defecto 80 % en lugar de 100 %, porque una disputa o una entrega incompleta detienen una factura llegue en el formato que llegue. Supuesto nuestro (nota D).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.errMins', 'es', 'Tiempo efectivo de trabajo para resolver una factura que llegó con datos incorrectos: reclamar al proveedor, volver a capturar, conseguir que se apruebe de nuevo. Valorado a la tarifa de captura de datos de abajo. ATO: 15 minutos para una excepción de tramitación, 5 para una simple corrección de captura (nota B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.errRate', 'es', 'Proporción de facturas tramitadas manualmente con un error que exige retrabajo. Dimensiona la fila de retrabajo. Consulta de HMRC / DBT, 2025, que afirma un 10 % y no cita ningún estudio para ello (nota B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.fteCost', 'es', 'Costo anual totalmente cargado de un ETC fiscal o financiero. Dimensiona únicamente el ahorro indirecto en esfuerzo fiscal, y lleva tope. Deliberadamente distinto de la tarifa de captura contigua — en torno al doble, y rara vez deslocalizado. Salario del BLS cargado con el factor de costo del empleador del BLS (nota B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.fteEntry', 'es', 'Costo anual totalmente cargado del puesto de captura o de correspondencia que recibe las facturas de proveedor. Expresa el ahorro de procesamiento en términos de plantilla; no añade nada por sí mismo. BLS Data Entry Keyers, cargado (nota B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.integrations', 'es', 'Cada país para el que tiene que construir, contado una vez por sistema ERP o de facturación, valorado a su tarifa simple o compleja. No se modelan economías de escala más allá de los primeros países, lo que hace esta cifra conservadora en vez de optimista.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.lanes', 'es', 'Cuántos frentes de país puede dotar realmente de personal a la vez. Cambia el tiempo transcurrido y el último inicio responsable; nunca el esfuerzo total. Supone capacidad constante — sin curva de aprendizaje entre países.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.nomandate', 'es', 'Países que ha seleccionado y que hoy no tienen ninguna obligación, cuantificados a la tarifa simple. Comparten la banda sin fecha límite fija con países donde el mandato ya está plenamente en vigor — pero solo estos son opcionales. Los demás van con retraso.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.pace', 'es', 'Un único multiplicador aplicado a cada duración de fase. Ambicioso (×0,75) supone una plataforma probada y un equipo dedicado; Conservador (×1,3) supone recursos compartidos y una gobernanza normal. Un mando de criterio, no una referencia.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.savePct', 'es', 'Cuánto del costo por factura elimina la automatización, aplicado a las bases de AP y AR. Valor por defecto 60 %, el suelo del rango 60–80 % de HMRC; los costos de canal de la ATO implican de forma independiente un 67–70 % (nota B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.scope', 'es', 'Solo cumplimiento modela el mandato como un frente de TI, que es lo que compran la mayoría de los programas: se ahorran la captura y la emisión, no la revisión ni la aprobación. El alcance más amplio añade el rediseño de procesos y una fase de cambio a cada frente de país.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.vida', 'es', 'La Directiva (UE) 2025/516 del Consejo hace obligatorias la facturación electrónica estructurada y el reporte digital para el B2B intracomunitario a partir del 1 de julio de 2030, vinculando a los 27 Estados miembros hayan legislado o no a nivel nacional. Valorada como COMPLEJA porque conlleva una obligación de reporte.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.volAP', 'es', 'Facturas de proveedor recibidas en un año, en todas las entidades del alcance. Cuente documentos, no pedidos ni líneas — todas las referencias aquí son por documento. Determina el ahorro de AP y la fila de retrabajo.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.volAR', 'es', 'Facturas a cliente que usted emite en un año. Es en lo que muerden los mandatos: los regímenes de clearance y de reporte regulan lo que envía, no lo que recibe. Determina el ahorro de AR.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.arShare', 'es', 'E-facturas emitidas hoy %');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.cImplC', 'es', 'Costo por integración COMPLEJA');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.cImplS', 'es', 'Costo por integración SIMPLE');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.cPlat.derived', 'es', 'Aproximado: {vol} facturas &times; {fee} cada una. Es un multiplicador aproximado por factura para la tecnología &mdash; el precio real de su proveedor será distinto, y es el que debe introducirse aquí.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.cPlat2', 'es', 'Cuotas de software al año');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.cRun', 'es', 'Costos internos de funcionamiento al año');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.costAR', 'es', 'Costo AR por factura');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.costNow', 'es', 'Costo AP por factura');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.countries', 'es', 'Países en el alcance');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.countryNoMatch', 'es', 'No hay coincidencias. Vacíe la búsqueda para ver todos los países.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.countrySearch', 'es', 'Buscar entre 70 países');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.currency', 'es', 'Moneda');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.eShare', 'es', 'E-facturas recibidas hoy %');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.erp', 'es', 'Integraciones ERP / facturación');
