INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.emptyChart', 'es', 'Ningún país seleccionado tiene a la vez una fecha límite futura y un mandato para el que construir, así que no hay cronología de despliegue que dibujar. Los países donde el mandato ya está en vigor necesitan igualmente trabajo de puesta al día &mdash; véase la tabla de abajo.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.emptyTable', 'es', 'Ningún país seleccionado tiene una fecha límite futura. Aquellos donde el mandato ya está en vigor necesitan igualmente trabajo de puesta al día &mdash; véase la lista de mandatos en vigor de abajo.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.euWide', 'es', 'La Directiva (UE) 2025/516 del Consejo vincula a todos los Estados miembros de la UE a partir del 1 de julio de 2030, con independencia de que legislen su propio mandato nacional. {0}');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.euWide.h', 'es', 'Obligación a escala de la UE.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.inforce', 'es', '<strong>Ya en vigor, sin más pasos con fecha ({0}):</strong> {1}. Son asuntos de cumplimiento inmediato, no líneas de un plan de proyecto.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.intro', 'es', 'Planificado hacia atrás desde la fecha límite publicada de cada país {0}, a través de duraciones de fase que usted controla {1}.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.intro3', 'es', 'Las compras se modelan una sola vez, no por país.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.intro4', 'es', 'Una de estas olas es la obligación europea y no un mandato nacional; cubre los {0} que ha seleccionado.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.noMandate', 'es', '<strong>Sin mandato, incluidos por su selección ({0}):</strong> {1}. Cuantificados a la tarifa simple y planificados como una única ola discrecional &mdash; no hay fecha límite que incumplir, así que este trabajo puede empezar cuando tenga capacidad.');
