-- ---- 31 benchmarks: hint and citation, label '' ----------------------
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'Media de mercado de Ardent Partners, datos de 2025', 'Ardent Partners, <em>The State of ePayables 2025</em>, publicado el 22 de ene. de 2026. Costo medio de mercado por factura: 9,84 USD, sobre 204 profesionales de AP. De acceso libre y primaria.' FROM roi_benchmarks WHERE key = 'ap_cost_per_invoice';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'Mediana de APQC Open Standards Benchmarking', 'APQC Open Standards Benchmarking, indicador &ldquo;number of invoices processed per FTE that performs the process process accounts payable&rdquo;: <strong>mediana de 12.000 por ETC y año</strong>. Primaria, atribuible y expuesta públicamente en la página del indicador; los valores por cuartil están reservados a los socios de APQC y aquí no se usan. APQC informa además de que los mejores son unas cinco veces más productivos que los últimos, así que una mediana aislada esconde una dispersión muy amplia &mdash; en este modelo solo sirve para dar al volumen de facturas una relación defendible con la plantilla, nunca para afirmar qué debería lograr una empresa concreta.' FROM roi_benchmarks WHERE key = 'ap_invoices_per_fte';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'Obtenido de las cifras de ATO/Deloitte — véase la fuente', 'Obtenido del <em>Peppol eInvoicing value assessment</em> de la Australian Taxation Office / Deloitte Access Economics: papel 30,87 AUD, PDF 27,67 AUD, e-factura 9,18 AUD, algo que la ATO presenta expresamente como <strong>una estimación de costo compartida entre emisor y receptor</strong>. La ATO publica también el reparto &mdash; <strong>40 % al proceso de cuentas por cobrar y 60 % al de cuentas por pagar</strong> &mdash; así que la parte de AR es la atribución de la propia ATO, no la nuestra.<br><br><strong>Nota B, y hasta el 16 de agosto de 2026 por el motivo equivocado.</strong> La fuente decía antes que la nota B se debía a que aislar una cifra solo de AR era derivación nuestra. No es así: la ATO publica ese reparto, en la misma página. Los motivos reales son que las estimaciones son australianas, datan de 2016, no llevan tamaño de muestra publicado y la conversión a dólares estadounidenses es nuestra. La misma nota, honestamente motivada &mdash; y corregirlo era necesario, porque quien encontrara la frase del reparto habría ascendido esta fila a A con razón, a la vista de la redacción anterior.' FROM roi_benchmarks WHERE key = 'ar_cost_per_invoice';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'Billentis sitúa Europa en 64 % y el mundo en 29 % — tomamos por defecto el más alto', 'La proporción de las facturas que usted EMITE que ya salen como e-facturas estructuradas. Ni PDF ni correo: un sistema de facturación que envía un PDF ha digitalizado el documento y no la transacción, y la ATO valora un PDF en 27,67 AUD frente a 30,87 AUD del papel y 9,18 AUD de una e-factura de verdad.<br><br><strong>Billentis, <em>Riding the Tornado</em> (2026)</strong>, es la única fuente que mide la EMISIÓN en lugar de la recepción &mdash; cuenta volumen transmitido en vez de encuestar bandejas de entrada. De unos 300.000 millones de facturas B2B en el mundo, alrededor de 87.000&ndash;88.000 millones son electrónicas: <strong>29 % en el mundo, en torno al 64 % en Europa, en torno al 78 % en América Latina</strong>.<br><br><strong>Valor por defecto 64 %, deliberadamente la cifra más alta de que disponemos.</strong> La medición mundial es del 29 %, y la proporción del lado receptor de Ardent implica un 51 %. El 64 % europeo está inflado por los países que ya han hecho la transición &mdash; Italia ronda el 97 % y llegó ahí por mandato &mdash; así que probablemente sea demasiado alto para un país cuyo mandato aún no ha llegado, que es justo el caso que cuantifica este planificador. Lo usamos igualmente, porque un caso de negocio debe equivocarse en su contra. <strong>Bájelo si conoce su propia situación</strong>; cada punto que quite aumenta el ahorro mostrado.<br><br>Nota B: Billentis es un organismo creíble que mide lo correcto, pero las cifras nos llegan a través de los resúmenes publicados del informe y no de nuestra lectura de la fuente primaria, y el denominador no es reproducible de forma independiente.' FROM roi_benchmarks WHERE key = 'ar_einvoice_share_now';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'La ATO reparte el costo compartido 60 AP / 40 AR', 'Australian Taxation Office, <em>Peppol eInvoicing value assessment</em>: los costos por factura que publica son <strong>una estimación de costo compartida entre emisor y receptor</strong>, y la ATO señala que &ldquo;for the purposes of this assessment 40% of this cost is attributed to the accounts receivable process and 60% to accounts payable&rdquo;. Se conserva aquí porque otras dos cifras de esta página dependen de ella. Nota B y no A: la ATO publica el reparto sin tamaño de muestra e indica que las estimaciones de base datan de 2016.' FROM roi_benchmarks WHERE key = 'ato_ap_cost_share';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'ATO / Deloitte, tiempos de tarea de facturas de compra', 'Australian Taxation Office / Deloitte Access Economics, <em>Peppol eInvoicing value assessment</em>: el proceso de una factura de compra se desglosa en recepción 7 minutos, validación 2, revisión 7 y aprobación 5 &mdash; 21 minutos en total, de los cuales <strong>9 minutos (43 %) son recepción y validación</strong>, el trabajo de captura que elimina la facturación electrónica. La misma página indica que la mayor parte del costo del papel y del PDF &ldquo;is attributable to the manual work required to enter the invoice data into your systems&rdquo;, y por eso la referencia por factura no puede contarse ADEMÁS como un ahorro de plantilla. La revisión y la aprobación son del lado del negocio y no se supone que desaparezcan. La ATO indica que estos tiempos datan de 2016.' FROM roi_benchmarks WHERE key = 'capture_share_of_ap';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'VALOR PROVISIONAL — no existe ninguna referencia creíble', 'Un valor provisional, no una referencia. Ninguna firma de analistas publica costos de implantación creíbles por país para la facturación electrónica &mdash; se comprobó directamente. Sustitúyalo por sus propias ofertas antes de enseñarle a nadie la cifra de recuperación.' FROM roi_benchmarks WHERE key = 'cost_per_integration';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'VALOR PROVISIONAL — una conexión CTC o de 5 esquinas', 'Estimación profesional de Dan para conectar un sistema de facturación a un país CTC o de 5 esquinas, donde la administración tributaria es parte de la transacción. No es una referencia, por el mismo motivo que la tarifa simple. Sustitúyala por una oferta de proveedor.' FROM roi_benchmarks WHERE key = 'cost_per_integration_complex';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'VALOR PROVISIONAL — una conexión descentralizada de 4 esquinas', 'Estimación profesional de Dan para conectar un sistema de facturación a un país de 4 esquinas. No es una referencia: ninguna firma de analistas publica costos de implantación creíbles por país para la facturación electrónica, algo que la auditoría de evidencias confirmó en diez de ellas. Sustitúyala por una oferta de proveedor.' FROM roi_benchmarks WHERE key = 'cost_per_integration_simple';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'HMRC 60–80 %; los datos de canal de la ATO implican 67–70 %', 'Consulta de HMRC / DBT, 13 de feb. de 2025: &ldquo;Industry estimates suggest that moving to e-invoicing reduces invoicing costs by 60-80%.&rdquo; <strong>HMRC no cita ningún estudio</strong> &mdash; comprobado contra la consulta original &mdash; y Ardent Partners publica el mismo rango para <em>una automatización completa de AP frente a métodos manuales y en papel</em>, que es un programa mayor que el cumplimiento por sí solo.<br><br><strong>Aun así el rango está respaldado, por una medición de canal independiente.</strong> El Peppol value assessment de la ATO valora una factura en papel en 30,87 AUD, un PDF en 27,67 y una e-factura en 9,18. Esas proporciones implican una <strong>reducción del 70,3 % desde el papel y del 66,8 % desde el PDF</strong> &mdash; sin escala, así que ni la moneda ni el reparto emisor/receptor las afectan, y caen de lleno en el rango de HMRC. Dos fuentes sin relación, dos métodos, una respuesta.<br><br><strong>Valor por defecto 60 %, el suelo en lugar del punto medio.</strong> La ATO respaldaría un 67 %. Una cifra conservadora por debajo de un rango corroborado es mejor posición que su centro, y este dato de entrada es suyo para subirlo si su punto de partida es realmente el papel.' FROM roi_benchmarks WHERE key = 'cost_reduction_pct';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'Ardent Partners, datos de 2025', 'Ardent Partners, <em>The State of ePayables 2025</em>: tiempo de ciclo medio del mercado 8,2 días; Best-in-Class 2,9 días frente a 13,5 del resto. <strong>Deliberadamente NO se ofrece como prueba de que la facturación electrónica acorte el tiempo de ciclo.</strong> Ardent define Best-in-Class como el 20 % de empresas con los costos de tramitación más bajos y los &ldquo;shortest average invoice process times&rdquo; &mdash; el tiempo de ciclo forma parte de la definición, así que la brecha del 79 % es una tautología y no un hallazgo. La cifra se cita aquí para que conste, y el motivo para no apoyarse en ella también.' FROM roi_benchmarks WHERE key = 'cycle_time_days';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'OCDE, ene. 2026 — el mecanismo, no la magnitud', 'OCDE, <em>Digital Continuous Transactional Reporting for Value Added Tax</em>, 9 de ene. de 2026: el DCTR &ldquo;typically requires the (near) real-time reporting of invoices or transactional data to tax authorities, most often with the objective of strengthening VAT compliance and risk management.&rdquo; Establece el mecanismo; son orientaciones de diseño y no un estudio de resultados, así que no respalda ningún porcentaje.' FROM roi_benchmarks WHERE key = 'dctr_mechanism';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'La media de mercado es del 51 % — la cifra que importa es la suya', 'La proporción de sus facturas de proveedor que YA llegan como e-facturas estructuradas. No PDF: un PDF aún hay que leerlo y capturarlo, y la ATO lo valora en 27,67 AUD frente a 30,87 AUD del papel y 9,18 AUD de una e-factura de verdad. <strong>Es la mayor palanca sobre la fila del costo de procesamiento</strong>, porque un ahorro solo se puede tomar una vez &mdash; lo que ya llega estructurado ya lo ha materializado. Fijado por defecto en el 50 %, cerca de la media de mercado, por indicación de Dan; ajústelo a su situación, y a 0 si parte de cero.' FROM roi_benchmarks WHERE key = 'einvoice_share_now';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'Supuesto nuestro — deliberadamente no el 100 %', 'Supuesto nuestro, no una referencia. Los datos de factura estructurados eliminan el error administrativo en el punto de captura, pero <strong>no toda excepción es un error administrativo</strong> &mdash; un precio en disputa, una entrega incompleta o un pedido de compra que falta seguirán deteniendo una factura por limpios que llegaran los datos, y ningún formato resuelve un desacuerdo comercial. El 80 % es un recorte deliberado sobre el supuesto de que la mayor parte, no la totalidad, de la carga actual de excepciones es calidad de datos.<br><br><strong>Qué respalda Ardent y qué no.</strong> Ardent Partners enuncia el mecanismo directamente &mdash; &ldquo;eInvoicing drives process efficiencies by eliminating data capture and manual data entry&rdquo; &mdash; e informa de que el 48 % de los profesionales de AP señalan una tasa alta de excepciones entre sus mayores retos. Pero el informe no contiene <strong>ningún desglose de las excepciones por causa</strong> ni <strong>ninguna reducción cuantificada</strong> por la automatización, así que no puede ni confirmar ni refutar el 80 %. Mecanismo respaldado, magnitud nuestra: la misma posición probatoria que la OCDE en la capa indirecta.<br><br>Sí fija en cambio un <strong>techo</strong>, que ahora se aplica. Véase el margen de reducción de excepciones junto a esta fila.' FROM roi_benchmarks WHERE key = 'error_elimination_pct';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'Ardent Partners, datos de 2025', 'Ardent Partners, <em>The State of ePayables 2025</em>: tasa de excepción media del mercado 18,4 %; Best-in-Class 11,1 % frente al 20,9 % del resto. Obsérvese que subió desde el 14 % de la edición anterior. <strong>No es intercambiable con la tasa de error manual del 10 % que usa este modelo</strong>: una excepción es cualquier factura que requiere intervención manual, un error es más estrecho, y sustituir discretamente una por otra casi duplicaría una línea del caso de negocio solo por un cambio de definición.' FROM roi_benchmarks WHERE key = 'exception_rate';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'Ardent Partners: Best-in-Class frente a todos los demás', 'Ardent Partners, <em>The State of ePayables 2025</em>: las organizaciones Best-in-Class registran una tasa de excepción del <strong>11,1 %</strong> frente al <strong>20,9 %</strong> del resto &mdash; una brecha de <strong>9,8 puntos porcentuales</strong>. Se usa aquí como TECHO y no como objetivo. Es la totalidad de la diferencia observada entre el cuartil más automatizado del mercado y todos los demás, sumando todas las causas de excepción; la facturación electrónica es un factor entre varios, ya que los Best-in-Class además procesan el 51 % de las facturas de extremo a extremo frente al 29 %, y tienen 1,4&times; más proveedores habilitados. Si la propia afirmación de este modelo (tasa de error &times; errores eliminados) supera los 9,8 puntos, está sosteniendo que la facturación electrónica por sí sola supera todo lo que hacen juntas las organizaciones Best-in-Class, y la página lo dice. <strong>Nota B: cifras de Ardent, resta nuestra.</strong> Obsérvese también que Ardent no publica ningún desglose de las excepciones por causa, así que nada aquí establece qué parte de esa brecha es administrativa.' FROM roi_benchmarks WHERE key = 'exception_reduction_pp';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'VALOR PROVISIONAL — sus propios costos de funcionamiento', 'Un valor provisional, no una referencia. Sus propios costos de funcionamiento son aquí el único dato de entrada con sentido.' FROM roi_benchmarks WHERE key = 'internal_run_cost';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'Salario mediano del BLS, cargado con el factor de costo del empleador del BLS', 'US Bureau of Labor Statistics, Occupational Employment and Wage Statistics: contables y auditores, salario anual mediano <strong>81.680 $</strong> (mayo de 2024). Cargado a <strong>&times;1,43</strong>, a partir de los BLS Employer Costs for Employee Compensation (marzo de 2026), donde los sueldos y salarios suponen el 69,9 % de la retribución total en el sector privado &mdash; así que el costo para el empleador es salario / 0,699. Da <strong>116.800 $</strong>. Nota B en vez de A porque ambos datos de entrada son primarios del BLS pero <strong>la multiplicación es nuestra</strong>, la misma base por la que el costo de AR por factura lleva nota B. Es la tarifa de quien hace el reporte fiscal y la preparación de auditorías, <em>no</em> de quien captura facturas &mdash; son trabajos distintos a aproximadamente el doble de precio, y hasta el 14 de agosto de 2026 un único campo valoraba ambos. Los gastos generales por encima de las cargas sociales legales no están incluidos; añádalos si su propia tarifa cargada los lleva.' FROM roi_benchmarks WHERE key = 'loaded_fte_cost';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'Salario mediano del BLS, cargado con el factor de costo del empleador del BLS', 'US Bureau of Labor Statistics, Occupational Employment and Wage Statistics: <strong>Data Entry Keyers</strong> (SOC 43-9021), salario anual mediano <strong>37.790 $</strong> (mayo de 2023); percentil diez 28.250 $, percentil noventa 55.330 $. Cargado a <strong>&times;1,43</strong> según los BLS Employer Costs for Employee Compensation (marzo de 2026), da <strong>54.000 $</strong>. Nota B: datos del BLS, multiplicación nuestra. <strong>Es una cifra estadounidense e interna, y la captura es la función más deslocalizada de finanzas</strong> &mdash; un centro de servicios compartidos en Cracovia, Lisboa o Manila estará sensiblemente por debajo, y quien conozca su propia tarifa debería usarla. Obsérvese además que el BLS proyecta una caída del 6 % de esta ocupación hasta 2034 y la atribuye a la automatización de tareas contables rutinarias, que es justo el efecto que cuantifica este modelo.' FROM roi_benchmarks WHERE key = 'loaded_fte_cost_entry';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'Consulta de HMRC — sin fuente dentro de ella', 'La misma consulta de HMRC / DBT: &ldquo;Manually entering supplier invoice data has an average error rate of approximately 10%.&rdquo; En el documento no se da ninguna fuente para esa cifra.' FROM roi_benchmarks WHERE key = 'manual_error_rate';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'Ardent Partners, datos de 2025', 'Ardent Partners, <em>The State of ePayables 2025</em>: el <strong>51,4 %</strong> de las facturas se reciben por vía electrónica frente al 48,6 % en papel. Se usa únicamente para descomponer el costo medio mixto de 9,84 $ en sus componentes manual y electrónico, de modo que la proporción propia del lector se aplique a la base correcta. <strong>Nota B en vez de A porque Ardent no define &ldquo;electronically&rdquo;</strong> &mdash; el informe no da ningún desglose por formato, así que no queda establecido si se cuentan los PDF enviados por correo. Medido, lo que es propio de la nota A; publicado sin denominador, lo que no lo es.' FROM roi_benchmarks WHERE key = 'market_einvoice_share';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'Un solo NHS trust — una anécdota, no una referencia', 'Guía del UK Small Business Commissioner, página actualizada el 16 de ene. de 2026: un NHS trust tramitó las e-facturas en 24 horas frente a 10 días en papel, cobró casi al doble de velocidad y vio caer las consultas de proveedores en torno a un 15 %. <strong>Una sola organización, sin nombre y sin fecha.</strong> Solo orientativo; nunca monetizado en este modelo.' FROM roi_benchmarks WHERE key = 'nhs_query_reduction';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'VALOR PROVISIONAL — depende por completo de su proveedor', 'Un valor provisional, no una referencia. Los precios de los proveedores en este mercado varían en un orden de magnitud y rara vez se publican.' FROM roi_benchmarks WHERE key = 'platform_cost_year';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'VALOR PROVISIONAL — un multiplicador aproximado por documento', 'Un valor provisional, no una referencia. Los precios de los proveedores en este mercado varían en un orden de magnitud y rara vez se publican; 0,40 USD por documento es una cifra redonda de orden de magnitud para cuotas de red y plataforma, no una media encuestada. El importe anual que produce debería sustituirse por la oferta de su propio proveedor.' FROM roi_benchmarks WHERE key = 'platform_fee_per_invoice';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'ATO / Deloitte: 15 min por una excepción de tramitación', 'Australian Taxation Office, <em>Peppol eInvoicing value assessment</em>. Excepciones en facturas de compra, con el tiempo medio atribuido a corregir cada una: <strong>pago en disputa 20 min</strong> (10 % de las facturas), <strong>excepción de tramitación 15 min</strong> (24 %), <strong>pago tardío 5 min</strong> (48 %), <strong>exactitud de datos 5 min</strong> (3,6 %). Fijado por defecto en la excepción de tramitación de 15 minutos, porque esta fila cubre la reclamación, la recaptura y la reaprobación y no una pulsación corregida &mdash; póngalo en 5 si solo se refiere a la pulsación, o en 20 si sus excepciones son realmente disputas.<br><br><strong>Es esfuerzo de trabajo, no tiempo transcurrido.</strong> La ATO convierte estos minutos en dinero con datos salariales de la Australian Bureau of Statistics, algo válido solo para tiempo efectivo. APQC publica muestras mayores para la resolución de excepciones &mdash; 5,0 días laborables (n=461) y 4,0 días naturales (n=2.861) &mdash; pero ambas son, por su propia definición, <em>transcurridas</em>, y multiplicar cualquiera de ellas por una tarifa salarial daría en torno a 1.000 $ por excepción.<br><br><strong>Nota B, y el motivo está en la procedencia y no en el editor.</strong> La ATO es primaria y de acceso libre, pero atribuye las estimaciones de base a Deloitte Access Economics y las data en 2016; no se publica tamaño de muestra para los tiempos en sí, y el informe de Deloitte no es de obtención pública. No queda establecido si son medidos o modelados &mdash; y eso es propio de la nota B, no de la A.<br><br><strong>Obsérvese que la tasa contigua viene de otra fuente.</strong> Este modelo usa la tasa de error manual del 10 % de HMRC; la propia tasa de excepción por exactitud de datos de la ATO es del 3,6 %. No son la misma medición &mdash; HMRC cuenta errores introducidos al capturar, la ATO cuenta excepciones abiertas &mdash; pero si quiere una metodología homogénea de principio a fin, ponga la tasa de error también en 3,6 %.' FROM roi_benchmarks WHERE key = 'rework_minutes';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'No existe ninguna referencia — estimación nuestra', 'Estimación nuestra. Ninguna firma de analistas publica un costo por excepción defendible; sustituir esto por el suyo es estrictamente mejor que nuestra suposición.' FROM roi_benchmarks WHERE key = 'rework_per_error';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'Ardent Partners, datos de 2025', 'Ardent Partners, <em>The State of ePayables 2025</em>: las organizaciones de AP Best-in-Class dedican el <strong>12,8 %</strong> del tiempo de su personal a consultas de proveedores frente al <strong>24,0 %</strong> del resto; la media de mercado del tiempo dedicado a proveedores en conjunto es del 21,9 %. Medido, primario y atribuible. <strong>Y algo decisivo: este indicador no forma parte de la definición de Best-in-Class de Ardent</strong> &mdash; eso es lo que lo hace utilizable donde la brecha de tiempo de ciclo no lo es. Sigue siendo una asociación con un AP de alto rendimiento en su conjunto: Ardent no aísla la facturación electrónica y solo informa de que los mejores tienen 1,4&times; más proveedores habilitados para facturar electrónicamente y 1,8&times; más procesamiento de extremo a extremo. <strong>No aporta ningún valor en este modelo.</strong>' FROM roi_benchmarks WHERE key = 'supplier_inquiry_time';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'VALOR PROVISIONAL — supuesto nuestro, como proporción', 'Un tope sobre la tasa por país, porque la magnitud es un supuesto y un supuesto sin tope se dispara: se reconoce como máximo el <strong>20 %</strong> del esfuerzo de AP que implica su volumen, por muchos países que se seleccionen. Reducido desde el 36 % el 14 de agosto de 2026, <strong>a la vez que la tarifa del ETC fiscal subía de 62.000 $ a 116.800 $</strong>, porque ambas se multiplican y corregir una sin la otra agrava el error en lugar de arreglarlo. El 36 % suponía que la facturación electrónica por sí sola eliminaba la mayor parte de una función fiscal, lo que no es defendible; el 20 % son unos 1,67 ETC repartidos entre 25 países con clearance, aproximadamente tres semanas al año de menor conciliación y preparación de muestras de auditoría en cada uno. Sigue siendo nuestra cifra, sigue siendo nota D, y sigue siendo la primera que hay que discutir.' FROM roi_benchmarks WHERE key = 'tax_effort_cap';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'VALOR PROVISIONAL — supuesto nuestro, como proporción', 'Supuesto nuestro, no una referencia: cada país con clearance o con reporte a nivel de factura se modela como si situara el 1,8 % del esfuerzo de AP que implica su volumen dentro del alcance de un reporte fiscal y una preparación de auditorías más ligeros. No se afirma nada sobre ello. Se expresa como PROPORCIÓN y no como plantilla para que escale con el tamaño del negocio; con el valor por defecto de la página de 100.000 facturas de AP equivale exactamente a los 0,15 ETC fijos por país a los que sustituye.' FROM roi_benchmarks WHERE key = 'tax_effort_per_jurisdiction';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'Muy citado, no defendible en términos causales', 'Caídas de la brecha del IVA muy citadas para Hungría (10,4 %&rarr;4,4 %), Italia (21,8 %&rarr;10,8 %), Polonia (12,5 %&rarr;3,3 %) y España (6,1 %&rarr;0,8 %), 2019&ndash;21. <strong>Dos correcciones de la verificación:</strong> son cifras de la Comisión Europea / CASE, no de la OCDE; y los propios análisis por país de la Comisión para Hungría, Italia y Polonia acreditan la recuperación económica tras la pandemia en lugar del reporte digital. <strong>No aporta ningún valor en ninguna parte de este modelo.</strong>' FROM roi_benchmarks WHERE key = 'vat_gap_context';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'es', '', 'Supuesto nuestro — una construcción de reporte sobre una plataforma existente', 'Supuesto nuestro, no una referencia. Un Estado miembro de la UE con una fecha límite nacional anterior a julio de 2030 afronta una segunda obligación: el requisito de reporte digital de la Directiva (UE) 2025/516 del Consejo. Se modela como <strong>la mitad</strong> de una integración de país completa, porque para entonces la plataforma, la conexión al punto de acceso y los datos maestros ya existen, y la selección de proveedor y la contratación se modelan una sola vez a nivel de programa y no se repiten. Lo realmente nuevo es la extracción para el reporte, su transmisión a la administración tributaria y su prueba. No se afirma nada sobre la cifra: una segunda integración completa cobraría dos veces por una plataforma comprada una sola vez, y cero mostraría la fecha límite negando el trabajo. Si su construcción de 2027 ya produce una extracción de reporte conforme, bájelo.' FROM roi_benchmarks WHERE key = 'vida_second_wave_ratio';

-- ---- 7 phases --------------------------------------------------------
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'es', 'Selección de proveedor', 'A nivel de programa: una vez para todo el programa, no una por país. Estudio de mercado, licitación, demostraciones y llamadas de referencia. Dimensionado según el país más complejo del alcance — un solo régimen de clearance en la lista significa que está comprando una plataforma capaz de clearance.' FROM roi_phases WHERE key = 'vendor';
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'es', 'Contratación', 'A nivel de programa: una vez, no una por país. Condiciones comerciales, jurídico, revisión de seguridad, firma. La fase que más se retrasa, y va por delante de cada frente de país — por eso aquí el camino crítico son las compras y no la entrega.' FROM roi_phases WHERE key = 'contract';
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'es', 'Movilización', 'Por país. Equipo constituido, alcance confirmado con los responsables locales de finanzas e impuestos, acceso concedido al ERP de ese país. Estimación de profesionales para un despliegue sobre una plataforma ya implantada — no una movilización de programa ERP, varias veces más larga.' FROM roi_phases WHERE key = 'mobilise';
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'es', 'Diseño', 'Por país. Trasladar el mandato local a sus datos: correspondencia de campos, lagunas en los datos maestros, el flujo de clearance o de reporte, el archivo. Escala con la complejidad del país y con cuántos sistemas tienen que alimentarlo.' FROM roi_phases WHERE key = 'design';
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'es', 'Construcción', 'Por país. Configurar e integrar — conector, transformación, validación, gestión de errores. La fase técnica más larga y donde está el trabajo de verdad. Escala con la complejidad y el número de sistemas exactamente igual que el diseño.' FROM roi_phases WHERE key = 'build';
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'es', 'UAT &amp; salida a producción', 'Por país. Prueba de extremo a extremo con la administración tributaria o el punto de acceso, certificación donde un país la exija, y luego salida a facturación real. Corta, porque un UAT de facturación electrónica es una prueba de integración estrecha — pero depende de tiempos de respuesta de la administración que usted no controla.' FROM roi_phases WHERE key = 'uat';
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'es', 'Cambio de procesos &amp; formación', 'Solo aparece si la automatización del proceso de AP está en el alcance. Rediseño de procesos, reciclaje formativo, incorporación de proveedores — la fase que hace reales los ahorros directos. Más larga que las fases técnicas, y recae en el negocio y no en TI, por lo que el cumplimiento por sí solo no los materializa.' FROM roi_phases WHERE key = 'change';

